import { useCedrosLoginOptional } from '../context/useCedrosLogin';
import type { AuthState, AuthUser, CedrosLoginConfig } from '../types';
import { useCedrosLoginAdminRuntimeOptional } from '../admin/CedrosLoginAdminRuntimeContext';

const NOOP_ACCESS_TOKEN = () => null;

export interface CedrosLoginAdminClientContextValue {
  config: Pick<CedrosLoginConfig, 'serverUrl' | 'requestTimeout' | 'retryAttempts'>;
  user: AuthUser | null;
  authState: AuthState;
  _internal: {
    getAccessToken: () => string | null;
  };
}

/**
 * Returns the shared transport/auth inputs used by login admin hooks.
 *
 * Inside AdminShell, the host-service runtime is preferred so hooks no longer
 * depend on CedrosLoginContext. Outside AdminShell, the legacy CedrosLogin
 * provider remains a compatibility fallback.
 */
export function useCedrosLoginAdminClientContext(): CedrosLoginAdminClientContextValue {
  const adminRuntime = useCedrosLoginAdminRuntimeOptional();
  const cedrosLogin = useCedrosLoginOptional();

  if (adminRuntime) {
    return {
      config: adminRuntime.config,
      user: adminRuntime.user,
      authState: adminRuntime.authState,
      _internal: {
        getAccessToken: adminRuntime.getAccessToken,
      },
    };
  }

  if (cedrosLogin) {
    return {
      config: cedrosLogin.config,
      user: cedrosLogin.user,
      authState: cedrosLogin.authState,
      _internal: {
        getAccessToken: cedrosLogin._internal?.getAccessToken ?? NOOP_ACCESS_TOKEN,
      },
    };
  }

  throw new Error(
    'Login admin hooks require CedrosLoginAdminSectionWrapper or CedrosLoginProvider'
  );
}
